def curvature_t(strain, stress):
    """t-statistic of a quadratic term; |t| > ~2.4 (df=7) hints at curvature."""
    design = np.column_stack([np.ones_like(strain), strain, strain**2])
    coef, *_ = np.linalg.lstsq(design, stress, rcond=None)
    residual = stress - design @ coef
    dof = len(strain) - design.shape[1]
    sigma2 = np.sum(residual**2) / dof
    cov = sigma2 * np.linalg.inv(design.T @ design)
    return coef[2] / np.sqrt(cov[2, 2])


